def solve(nums: list[int], k: int) -> int:
    first_seen = {0: -1}
    prefix_sum = 0
    longest = 0

    for i, num in enumerate(nums):
        prefix_sum += num
        remainder = prefix_sum % k

        if remainder in first_seen:
            longest = max(longest, i - first_seen[remainder])
        else:
            first_seen[remainder] = i

    return longest
